mdl = 'autoBuilt';
if bdIsLoaded(mdl), bdclose(mdl); end
new_system(mdl, 'Model', 'ErrorIfShadowed');
save_system(mdl, fullfile(tempdir, mdl));

load_system('vdp');
stopTime = get_param('vdp', 'StopTime')
blks = find_system('vdp', 'BlockType', 'Integrator');
close_system('vdp', 0);

open_system('vdp');
open_system('vdp/Mu', 'parameter');
set_param('vdp', 'Open', 'off');   % close the window, keep it loaded

load_system('vdp');
set_param('vdp', 'StopTime', '40');
f = save_system('vdp', fullfile(tempdir,'vdp_copy.slx'), 'OverwriteIfChangedOnDisk', true)

load_system('vdp');
set_param('vdp/Mu', 'Gain', '2');
close_system('vdp', 0);   % discard the edit and unload

bdclose('all');
new_system('rig');
load_system('rig');
bdclose('rig');

load_system('vdp');
gains = find_system('vdp', 'BlockType', 'Gain')
sines = find_system('vdp', 'RegExp', 'on', 'Name', '^Scope')
lines = find_system('vdp', 'FindAll', 'on', 'Type', 'line');

load_system('vdp');
set_param('vdp', 'StopTime', '40', 'Solver', 'ode45');
set_param('vdp/Mu', 'Gain', '1.5');
set_param('vdp/Mu', 'Position', [150 100 180 130]);

mdl = 'demoBuild';
new_system(mdl); load_system(mdl);
add_block('simulink/Sources/Sine Wave', [mdl '/Src'], 'Amplitude', '2', 'Position', [50 50 80 80]);
add_block('simulink/Sinks/Scope', [mdl '/Sink'], 'Position', [200 50 230 80]);
add_line(mdl, 'Src/1', 'Sink/1');

load_system('f14');
h = getSimulinkBlockHandle('f14/Controller/Pitch Rate Lead Filter');
delete_line('f14/Controller', 'Pitch Rate Lead Filter/1', 'Gain3/1');
delete_block(h);

mdl = 'wiring';
new_system(mdl); load_system(mdl);
add_block('simulink/Sources/Step', [mdl '/Step'], 'Position', [40 40 70 70]);
add_block('simulink/Sinks/Scope', [mdl '/Scope'], 'Position', [200 40 230 70]);
ph1 = get_param([mdl '/Step'], 'PortHandles');
ph2 = get_param([mdl '/Scope'], 'PortHandles');
add_line(mdl, ph1.Outport(1), ph2.Inport(1), 'autorouting', 'smart');

load_system('vdp');
lh = get_param('vdp/Mu', 'LineHandles');
delete_line(lh.Inport(1));
close_system('vdp', 0);

load_system('vdp'); open_system('vdp');
sys = gcs
add_block('simulink/Sources/Constant', [sys '/K'], 'Value', '3');

h = getSimulinkBlockHandle('f14/Pilot', true);
if h ~= -1
    get_param(h, 'WaveForm')
    set_param(h, 'WaveForm', 'sine');
end

out = sim('vdp', 'StopTime', '20');
disp(out.who);
ds = out.logsout;
sig = ds.get('x1').Values;
plot(sig.Time, sig.Data);
md = out.getSimulationMetadata;
fprintf('solver %s, %.2f s wall clock\n', ...
    md.ModelInfo.SolverName, md.TimingInfo.ExecutionElapsedWallTime);

mdl = 'vdp'; load_system(mdl);
muVals = [0.5 1 2];
for k = numel(muVals):-1:1
    simIn(k) = Simulink.SimulationInput(mdl);
    simIn(k) = simIn(k).setBlockParameter([mdl '/Mu'], 'Gain', num2str(muVals(k)));
    simIn(k) = simIn(k).setModelParameter('StopTime', '20');
end
out = sim(simIn);

out = sim('vdp', 'StopTime', '30', 'CaptureErrors', 'on');
t = out.tout;
y = out.yout;
disp(out.SimulationMetadata.TimingInfo)

mdl = 'vdp'; load_system(mdl);
mu = linspace(0.5, 3, 12);
for k = numel(mu):-1:1
    in(k) = Simulink.SimulationInput(mdl);
    in(k) = in(k).setBlockParameter([mdl '/Mu'], 'Gain', num2str(mu(k)));
end
out = parsim(in, 'ShowProgress', 'on', 'TransferBaseWorkspaceVariables', 'on');
